import React, { useState, useEffect } from "react";
import api from "../../api";
import { FaPlus } from "react-icons/fa";
import Create from "../form/artikel/create";
import Update from "../form/artikel/update";

const Article = () => {
  const [data, setData] = useState([]);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showUpdateModal, setShowUpdateModal] = useState(false);
  const [currentData, setCurrentData] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    api.get("/artikel")
      .then((response) => {
        setData(response.data.articles);
      })
      .catch((error) => {
        console.error("Error fetching data:", error);
      });
  }, []);

  const handleOpenCreateModal = () => {
    setShowCreateModal(true);
  };

  const handleOpenUpdateModal = (row) => {
    setCurrentData(row);
    setShowUpdateModal(true);
  };

  const handleCloseModal = () => {
    setShowCreateModal(false);
    setShowUpdateModal(false);
    setCurrentData(null);
  };

  const handleSubmitCreate = (formData) => {
    setLoading(true);

    api.post("/artikel/create", formData)
      .then((response) => {
        setData([...data, response.data]);
        setShowCreateModal(false);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error submitting form:", error);
        setLoading(false);
      });
  };

  const handleSubmitUpdate = (formData) => {
    setLoading(true);

    api.put(`/artikel/update/${currentData.id}`, formData)
      .then((response) => {
        const updatedData = data.map((item) =>
          item.id === currentData.id ? response.data : item
        );
        setData(updatedData);
        setShowUpdateModal(false);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error updating form:", error);
        setLoading(false);
      });
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this artikel?")) {
      api.delete(`/artikel/delete/${id}`)
        .then(() => {
          setData(data.filter((item) => item.id !== id));
        })
        .catch((error) => {
          console.error("Error deleting item:", error);
        });
    }
  };

  return (
    <div>
      <button
        onClick={handleOpenCreateModal}
        className="bg-teal-500 text-white py-2 px-4 rounded-lg mb-4 flex items-center"
      >
        <FaPlus className="inline-block mr-2 mb-1" /> Create Article
      </button>

      <div className="grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
          <thead className="bg-teal-700 text-white">
            <tr>
              <th className="px-6 py-3 text-left font-medium">No</th>
              <th className="px-6 py-3 text-left font-medium">Title</th>
              <th className="px-6 py-3 text-left font-medium">Description</th>
              <th className="px-6 py-3 text-left font-medium">Actions</th>
            </tr>
          </thead>
          <tbody>
            {data.length > 0 ? (
              data.map((row, index) => (
                <tr key={row.id}>
                  <td className="px-6 py-4">{index + 1}</td>
                  <td className="px-6 py-4">{row.judul}</td>
                  <td className="px-6 py-4">{row.keterangan}</td>
                  <td className="px-6 py-4 flex gap-2">
                    <button
                      onClick={() => handleOpenUpdateModal(row)}
                      className="bg-teal-500 text-white py-1 px-3 rounded-lg"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => handleDelete(row.id)}
                      className="bg-red-500 text-white py-1 px-3 rounded-lg"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="4" className="text-center px-6 py-4 text-gray-500">
                  No articles available.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {showCreateModal && (
        <Create
          onSubmit={handleSubmitCreate}
          onClose={handleCloseModal}
          loading={loading}
        />
      )}

      {showUpdateModal && (
        <Update
          onSubmit={handleSubmitUpdate}
          onClose={handleCloseModal}
          initialData={currentData}
          loading={loading}
        />
      )}
    </div>
  );
};

export default Article;
